@startuml

class Person {
  + personId : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + doi : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorRole {
  + position : int
}

class ReviewerRole {}

Person "1" -- "1" ResearchInstitution : worksFor
Person "1" -- "0..*" AuthorRole
AuthorRole "0..*" -- "1" ScientificArticle
Person "1" -- "0..*" ReviewerRole
ReviewerRole "0..*" -- "1" PeerReviewedPaper

PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

ResearchInstitution "1" -- "0..*" TechnicalReport : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes

Publisher "1" -- "0..*" Journal
PeerReviewedPaper "0..*" -- "0..1" Journal : publishedIn

@enduml

